<template>
  <section class="social-page community">
    <header class="community-head"><button v-if="thread" class="back" aria-label="목록으로" @click="thread=null">‹</button><h1>{{thread?'게시글':'커뮤니티'}}</h1></header>
    <p v-if="error" class="feedback" role="alert">{{error}}</p><p v-if="notice" class="feedback" role="status">{{notice}}</p>
    <template v-if="!thread">
      <nav class="board-tabs" aria-label="게시판"><button v-for="c in categories" :key="c[0]" :aria-current="category===c[0]?'page':undefined" :class="{selected:category===c[0]}" @click="category=c[0];load()">{{c[1]}}</button></nav>
      <div class="board-toolbar"><span>최근 이야기</span><button class="write-button" @click="editor.showModal()"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 5 4 4M4 20l5-1L20 8a2.8 2.8 0 0 0-4-4L5 15l-1 5Z"/></svg>글쓰기</button></div>
      <p v-if="!posts.length&&!busy" class="social-empty">아직 이야기가 없어요.<br>첫 글을 남겨보세요.</p>
      <p v-if="busy&&!posts.length" class="social-empty" role="status">불러오는 중…</p>
      <div class="post-list"><button v-for="p in posts" :key="p.id" class="post-preview" @click="open(p.id)"><div class="post-copy"><span class="category-label">{{label(p.category)}}</span><h2>{{p.title}}</h2><p>{{p.body}}</p><div class="post-meta"><span>{{p.author}}</span><i>·</i><time>{{date(p.createdAt)}}</time></div></div><img v-if="p.imageUrl" v-private-src="p.imageUrl" class="post-thumb" alt="첨부 사진" loading="lazy"/></button></div>
      <button v-if="more" class="load-more" :disabled="busy" @click="load(true)">{{busy?'불러오는 중…':'이야기 더 보기'}}</button>
    </template>
    <template v-else>
      <article class="post-detail"><span class="category-label">{{label(thread.post.category)}}</span><h2>{{thread.post.title}}</h2><div class="post-meta"><strong>{{thread.post.author}}</strong><i>·</i><time>{{date(thread.post.createdAt)}}</time></div><p class="post-body">{{thread.post.body}}</p><img v-if="thread.post.imageUrl" v-private-src="thread.post.imageUrl" class="detail-photo" alt="게시글 사진"/><div class="post-actions"><button @click="thread.post.mine?remove(thread.post):report(thread.post)">{{thread.post.mine?'삭제':'신고'}}</button></div></article>
      <h2 class="comments-heading">댓글 <span>{{thread.comments.length}}</span></h2><p v-if="!thread.comments.length" class="empty-comments">첫 댓글을 남겨보세요.</p>
      <article v-for="p in thread.comments" :key="p.id" class="comment"><strong>{{p.author}}</strong><p>{{p.body}}</p><footer><time>{{date(p.createdAt)}}</time><button @click="p.mine?remove(p):report(p)">{{p.mine?'삭제':'신고'}}</button></footer></article><small v-if="thread.comments.length===50">최근 댓글 50개를 표시합니다.</small>
      <form class="reply-form" @submit.prevent="reply"><textarea v-model="comment" maxlength="3000" required placeholder="댓글을 남겨주세요" aria-label="댓글"/><button class="primary" :disabled="busy||!comment.trim()">등록</button></form>
    </template>
    <dialog ref="editor" class="social-dialog community-editor" @cancel="busy&&$event.preventDefault()"><form @submit.prevent="create"><header><button type="button" :disabled="busy" @click="editor.close()">취소</button><h2>글쓰기</h2><button class="primary" :disabled="busy||photoBusy||!form.title.trim()||!form.body.trim()">{{busy?'등록 중':'등록'}}</button></header><label class="board-select">게시판<select v-model="form.category"><option v-for="c in categories.slice(1)" :key="c[0]" :value="c[0]">{{c[1]}}</option></select></label><input v-model="form.title" maxlength="80" required placeholder="제목을 입력해 주세요" aria-label="제목"/><textarea v-model="form.body" maxlength="3000" required placeholder="나누고 싶은 이야기를 적어주세요" aria-label="내용"/><div v-if="photoPreview" class="attachment"><img :src="photoPreview" alt="첨부할 사진"/><button type="button" aria-label="사진 삭제" @click="clearPhoto">×</button></div><button type="button" class="attach-button" :disabled="photoBusy||busy" @click="photoInput.click()"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 5-5 4 4 4-6 5 7"/></svg>{{photoBusy?'사진 준비 중…':photoPreview?'사진 변경':'사진 첨부'}}</button><input ref="photoInput" type="file" hidden accept="image/*" :disabled="photoBusy||busy" @change="choosePhoto"/><p v-if="error" class="feedback" role="alert">{{error}}</p></form></dialog>
  </section>
</template>
<script setup>
import {ref,onMounted,onUnmounted} from 'vue';import api from '../../api/api';import '../../components/social.css';
const posts=ref([]),thread=ref(null),editor=ref(),category=ref('ALL'),busy=ref(false),more=ref(false),error=ref(''),notice=ref(''),comment=ref(''),form=ref({category:'ADVICE',title:'',body:''});
const photoPreview=ref(''),photoBusy=ref(false),photoInput=ref();let photo=null,seq=0;
const categories=[['ALL','전체'],['ADVICE','고민 상담'],['DATING','연애 이야기'],['DAILY','일상']];const label=v=>categories.find(c=>c[0]===v)?.[1];
function date(v){const d=new Date(v),minutes=Math.max(0,Math.floor((Date.now()-d)/60000));return minutes<1?'방금 전':minutes<60?`${minutes}분 전`:minutes<1440?`${Math.floor(minutes/60)}시간 전`:d.toLocaleDateString('ko-KR',{month:'long',day:'numeric'});}
function clearPhoto(){if(photoPreview.value)URL.revokeObjectURL(photoPreview.value);photoPreview.value='';photo=null;}
async function choosePhoto(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;photoBusy.value=true;error.value='';let bitmap;try{bitmap=await createImageBitmap(file);const ratio=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.8));if(!blob)throw new Error();clearPhoto();photo=blob;photoPreview.value=URL.createObjectURL(blob);}catch{error.value='사진을 열 수 없어요. 다른 사진을 선택해 주세요.';}finally{bitmap?.close();photoBusy.value=false;}}
async function load(append=false){const id=++seq;busy.value=true;error.value='';try{const {data}=await api.get('/community',{params:{category:category.value,before:append?posts.value.at(-1)?.id:0}});if(id!==seq)return;posts.value=append?[...posts.value,...data]:data;more.value=data.length===20;}catch(e){error.value=e.response?.data?.message||'목록을 불러오지 못했어요.';}finally{if(id===seq)busy.value=false;}}
async function open(id){error.value='';try{thread.value=(await api.get(`/community/${id}`)).data;comment.value='';window.scrollTo({top:0});}catch(e){error.value=e.response?.data?.message||'게시글을 불러오지 못했어요.';}}
async function create(){if(busy.value||photoBusy.value)return;busy.value=true;error.value='';try{let payload=form.value;if(photo){payload=new FormData();Object.entries(form.value).forEach(([k,v])=>payload.append(k,v));payload.append('photo',photo,'community.jpg');}const {data}=await api.post('/community',payload);editor.value.close();form.value={category:'ADVICE',title:'',body:''};clearPhoto();await load();await open(data.id);}catch(e){error.value=e.response?.data?.message||'등록하지 못했어요.';}finally{busy.value=false;}}
async function reply(){if(busy.value)return;busy.value=true;error.value='';try{await api.post('/community',{parentId:thread.value.post.id,body:comment.value});await open(thread.value.post.id);}catch(e){error.value=e.response?.data?.message||'댓글을 등록하지 못했어요.';}finally{busy.value=false;}}
async function remove(p){if(!confirm('삭제할까요?'))return;try{await api.delete(`/community/${p.id}`);if(p.parentId)await open(p.parentId);else{thread.value=null;await load();}}catch(e){error.value=e.response?.data?.message||'삭제하지 못했어요.';}}
async function report(p){const reason=prompt('신고 사유를 입력해 주세요.');if(!reason)return;try{await api.post(`/community/${p.id}/report`,{reason});notice.value='신고를 접수했어요.';}catch(e){error.value=e.response?.data?.message||'신고하지 못했어요.';}}
onMounted(()=>load());onUnmounted(clearPhoto);
</script>
<style scoped>
.community{background:#fffcf9;min-height:calc(100dvh - 84px - var(--safe-area-inset-bottom,env(safe-area-inset-bottom,0px)))}.community-head{padding-right:54px;display:flex;gap:10px}.community-head h1{flex:1}.community .back{background:none;padding:0 12px 0 0;font-size:30px}
.board-tabs{display:flex;gap:22px;border-bottom:1px solid #eee5df;margin:0 -16px;padding:0 16px;overflow-x:auto;scrollbar-width:none}.community .board-tabs button{white-space:nowrap;border-radius:0;background:none;padding:12px 0 14px;font-size:14px;color:#96887f;position:relative}.community .board-tabs .selected{color:#3c2922;font-weight:750}.board-tabs .selected:after{content:'';position:absolute;bottom:0;left:0;right:0;height:3px;border-radius:3px;background:#d56f4e}
.board-toolbar{display:flex;align-items:center;justify-content:space-between;padding:18px 0 5px}.board-toolbar>span{font-size:12px;color:#9a8b82}.community .write-button{display:flex;align-items:center;gap:5px;font-size:12px;padding:8px 11px;background:#f6e9e1;border-radius:20px}.write-button svg,.attach-button svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.7}
.community .post-preview{display:flex;align-items:center;gap:16px;width:100%;border:0;border-bottom:1px solid #eee6e0;border-radius:0;background:transparent;text-align:left;padding:20px 0;color:#31211d}.post-copy{flex:1;min-width:0}.category-label{font-size:11px;color:#b16e53;font-weight:650}.post-preview h2{font-size:16px;line-height:1.45;font-weight:650;margin:7px 0 5px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;letter-spacing:-.025em}.post-preview p{font-size:13px;line-height:1.5;color:#8d7c72;margin:0 0 12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.post-meta{display:flex;align-items:center;gap:6px;font-size:11px;color:#a3958d}.post-meta i{font-style:normal}.post-thumb{width:76px;height:76px;flex:none;border-radius:12px;object-fit:cover;background:#f0e7df}.community .load-more{display:block;margin:24px auto;background:none;font-size:13px;color:#8c6b5a}
.post-detail{padding:10px 0 16px;border-bottom:1px solid #eee6e0}.post-detail h2{font-size:23px;line-height:1.45;letter-spacing:-.04em;margin:10px 0 14px}.post-body{white-space:pre-wrap;overflow-wrap:anywhere;font-size:15px;line-height:1.85;margin:28px 0 20px}.detail-photo{display:block;width:100%;border-radius:14px}.post-actions{display:flex;justify-content:flex-end;margin-top:16px}.community .post-actions button,.community .comment button{background:none;font-size:11px;padding:6px;color:#9f8e82}.comments-heading{font-size:15px;margin:24px 0 12px}.comments-heading span{color:#d56f4e;margin-left:4px}.empty-comments{font-size:13px;color:#a3958d;padding:18px 0}.comment{padding:18px 0;border-bottom:1px solid #eee6e0}.comment strong{font-size:13px}.comment p{white-space:pre-wrap;font-size:14px;line-height:1.7;margin:8px 0}.comment footer{display:flex;justify-content:space-between;align-items:center;font-size:11px;color:#a3958d}.reply-form{display:flex;align-items:flex-end;gap:8px;margin-top:20px}.reply-form textarea{flex:1;resize:vertical;min-height:46px;max-height:160px;border:1px solid #eee2da;border-radius:12px;padding:12px;font:inherit;font-size:16px;background:#fff}.reply-form button{height:46px}
.community-editor{padding:20px;width:calc(100% - 24px);max-height:calc(100dvh - 48px);border-radius:20px}.community-editor header{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}.community-editor header h2{font-size:17px;margin:0}.community-editor header button{font-size:13px;padding:9px 12px}.community-editor header button:first-child{background:none;color:#97877d}.board-select{display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#9b887b;padding-bottom:12px;border-bottom:1px solid #eee3dc}.board-select select{font:inherit;font-size:14px;background:transparent;border:0;color:#654a3c;padding:8px}.community-editor input:not([type=file]){display:block;width:100%;border:0;border-bottom:1px solid #eee3dc;padding:20px 0;font:inherit;font-size:18px;background:none;outline-color:#d56f4e}.community-editor textarea{display:block;width:100%;min-height:190px;border:0;resize:vertical;padding:20px 0;font:inherit;font-size:16px;line-height:1.7;background:none;outline-color:#d56f4e}.attach-button{display:inline-flex;align-items:center;gap:7px;border:1px solid #e7d9ce;padding:10px 12px;border-radius:10px;font-size:12px;cursor:pointer}.attach-button input{display:none}.attachment{position:relative;width:96px;height:96px;margin-bottom:16px}.attachment img{width:100%;height:100%;object-fit:cover;border-radius:12px}.attachment button{position:absolute;right:-6px;top:-6px;width:26px;height:26px;padding:0;border-radius:50%;background:#3c2922;color:white;font-size:18px}.feedback{font-size:13px;color:#a2553c;line-height:1.6}
</style>
